-- Additive portfolio domain. Public access is only through the current snapshot reader.
create extension if not exists pg_jsonschema with schema extensions;
create table public.portfolio_sites (
 id uuid primary key default auth.uid(), owner_id uuid not null unique default auth.uid() references auth.users(id),
 draft jsonb not null, revision integer not null default 1 check(revision>0),
 published_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(id=owner_id)
);
create table public.portfolio_versions (
 id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id),
 document jsonb not null, draft_revision integer not null, created_at timestamptz not null default now(),
 unique(owner_id,id)
);
alter table public.portfolio_sites add constraint portfolio_current_version foreign key(owner_id,published_id) references public.portfolio_versions(owner_id,id) deferrable initially deferred;
create table public.portfolio_media (
 id uuid primary key, owner_id uuid not null default auth.uid() references auth.users(id),
 path text not null unique, mime text not null check(mime='image/webp'), bytes integer not null check(bytes between 1 and 2097152), created_at timestamptz not null default now(),
 check(path=owner_id::text || '/portfolio/' || id::text || '.webp')
);
do $$ declare t text; begin foreach t in array array['portfolio_sites','portfolio_versions','portfolio_media'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy owner_only on public.%I to authenticated using(owner_id=(select auth.uid()) and (select private.is_owner()))',t);
end loop; end $$;
grant insert(id,path,mime,bytes) on public.portfolio_media to authenticated;
create policy owner_insert on public.portfolio_media for insert to authenticated with check(owner_id=(select auth.uid()) and (select private.is_owner()));

create function private.portfolio_media_ids(doc jsonb) returns setof uuid language sql immutable set search_path='' as $$
 select distinct substring(v #>> '{}' from 7)::uuid from jsonb_path_query(doc,'$.** ? (@.type() == "string")') v where (v #>> '{}') ~ '^media:[0-9a-f-]{36}$'
$$;

create function private.portfolio_nodes(doc jsonb) returns table(key text,value jsonb) language sql immutable set search_path='' as $$
 with recursive nodes(key,value) as (
 select ''::text,doc union all
 select child.key,child.value from nodes n cross join lateral (
 select e.key,e.value from jsonb_each(case when jsonb_typeof(n.value)='object' then n.value else '{}'::jsonb end) e
 union all select ''::text,a.value from jsonb_array_elements(case when jsonb_typeof(n.value)='array' then n.value else '[]'::jsonb end) a
 ) child
 ) select * from nodes
$$;
create function private.validate_portfolio(doc jsonb, owner uuid) returns boolean language plpgsql stable set search_path='' as $$
declare n record; v text; k text; schema json; normalized jsonb;
begin
 schema='{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"schemaVersion":{"type":"number","const":1},"sections":{"minItems":8,"maxItems":8,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","enum":["hero","about","work","education","certifications","skills","projects","contact"]},"visible":{"type":"boolean"}},"required":["id","visible"],"additionalProperties":false}},"locales":{"type":"object","properties":{"vi":{"type":"object","properties":{"name":{"type":"string","maxLength":10000},"nickname":{"type":"string","maxLength":10000},"initials":{"type":"string","maxLength":10000},"url":{"type":"string","maxLength":2000},"location":{"type":"string","maxLength":10000},"locationLink":{"type":"string","maxLength":2000},"description":{"type":"string","maxLength":10000},"summary":{"type":"string","maxLength":10000},"avatarUrl":{"type":"string"},"skills":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"name":{"type":"string","maxLength":10000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]}},"required":["id","name","icon"],"additionalProperties":false}},"navbar":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"href":{"type":"string","maxLength":2000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]},"label":{"type":"string","maxLength":10000}},"required":["id","href","icon","label"],"additionalProperties":false}},"contact":{"type":"object","properties":{"email":{"type":"string","maxLength":10000},"tel":{"type":"string","maxLength":10000},"social":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"name":{"type":"string","maxLength":10000},"url":{"type":"string","maxLength":2000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]},"navbar":{"type":"boolean"}},"required":["id","name","url","icon","navbar"],"additionalProperties":false}}},"required":["email","tel","social"],"additionalProperties":false},"work":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"company":{"type":"string","maxLength":10000},"companyContext":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"badges":{"maxItems":20,"type":"array","items":{"type":"string","maxLength":10000}},"location":{"type":"string","maxLength":10000},"title":{"type":"string","maxLength":10000},"logoUrl":{"type":"string"},"logoClassName":{"type":"string","enum":["bg-[#0B67B2] p-0.5",""]},"start":{"type":"string","maxLength":10000},"end":{"type":"string","maxLength":10000},"description":{"type":"string","maxLength":10000}},"required":["id","company","href","badges","location","title","logoUrl","start","description"],"additionalProperties":false}},"education":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"