["id","name","issuer","href","logoUrl"],"additionalProperties":false}},"copy":{"type":"object","properties":{"common":{"type":"object","propertyNames":{"type":"string","pattern":"^[a-zA-Z]+$"},"additionalProperties":{"type":"string","maxLength":2000}},"home":{"type":"object","propertyNames":{"type":"string","pattern":"^[a-zA-Z]+$"},"additionalProperties":{"type":"string","maxLength":2000}},"metadata":{"type":"object","properties":{"description":{"type":"string","maxLength":10000}},"required":["description"],"additionalProperties":false}},"required":["common","home","metadata"],"additionalProperties":false}},"required":["name","nickname","initials","url","location","locationLink","description","summary","avatarUrl","skills","navbar","contact","work","education","projects","certifications","copy"],"additionalProperties":false},"en":{"type":"object","properties":{"name":{"type":"string","maxLength":10000},"nickname":{"type":"string","maxLength":10000},"initials":{"type":"string","maxLength":10000},"url":{"type":"string","maxLength":2000},"location":{"type":"string","maxLength":10000},"locationLink":{"type":"string","maxLength":2000},"description":{"type":"string","maxLength":10000},"summary":{"type":"string","maxLength":10000},"avatarUrl":{"type":"string"},"skills":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"name":{"type":"string","maxLength":10000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]}},"required":["id","name","icon"],"additionalProperties":false}},"navbar":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"href":{"type":"string","maxLength":2000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]},"label":{"type":"string","maxLength":10000}},"required":["id","href","icon","label"],"additionalProperties":false}},"contact":{"type":"object","properties":{"email":{"type":"string","maxLength":10000},"tel":{"type":"string","maxLength":10000},"social":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"name":{"type":"string","maxLength":10000},"url":{"type":"string","maxLength":2000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]},"navbar":{"type":"boolean"}},"required":["id","name","url","icon","navbar"],"additionalProperties":false}}},"required":["email","tel","social"],"additionalProperties":false},"work":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"company":{"type":"string","maxLength":10000},"companyContext":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"badges":{"maxItems":20,"type":"array","items":{"type":"string","maxLength":10000}},"location":{"type":"string","maxLength":10000},"title":{"type":"string","maxLength":10000},"logoUrl":{"type":"string"},"logoClassName":{"type":"string","enum":["bg-[#0B67B2] p-0.5",""]},"start":{"type":"string","maxLength":10000},"end":{"type":"string","maxLength":10000},"description":{"type":"string","maxLength":10000}},"required":["id","company","href","badges","location","title","logoUrl","start","description"],"additionalProperties":false}},"education":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"school":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"degree":{"type":"string","maxLength":10000},"logoUrl":{"type":"string"},"start":{"type":"string","maxLength":10000},"end":{"type":"string","maxLength":10000}},"required":["id","school","href","degree","logoUrl","start","end"],"additionalProperties":false}},"projects":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"title":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"dates":{"type":"string","maxLength":10000},"active":{"type":"boolean"},"description":{"type":"string","maxLength":10000},"technologies":{"maxItems":50,"type":"array","items":{"type":"string","maxLength":120}},"links":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"type":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"icon":{"type":"string","enum":["Typescript","ReactLight","NextjsIconDark","Icons.tailwindcss","Docker","antdesign","reactquery","nestjs","socketdotio","redis","apachekafka","keycloak","mongodb","Postgresql","HomeIcon","CameraIcon","FolderKanbanIcon","BookOpenIcon","Icons.github","Icons.linkedin","Icons.facebook","Icons.instagram","Icons.x","Icons.youtube","Icons.email"]}},"required":["id","type","href","icon"],"additionalProperties":false}},"image":{"type":"string"},"video":{"type":"string","const":""}},"required":["id","title","href","dates","active","description","technologies","links","image","video"],"additionalProperties":false}},"certifications":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","pattern":"^[a-zA-Z0-9_-]{1,80}$"},"name":{"type":"string","maxLength":10000},"issuer":{"type":"string","maxLength":10000},"href":{"type":"string","maxLength":2000},"logoUrl":{"type":"string"}},"required":["id","name","issuer","href","logoUrl"],"additionalProperties":false}},"copy":{"type":"object","properties":{"common":{"type":"object","propertyNames":{"type":"string","pattern":"^[a-zA-Z]+$"},"additionalProperties":{"type":"string","maxLength":2000}},"home":{"type":"object","propertyNames":{"type":"string","pattern":"^[a-zA-Z]+$"},"additionalProperties":{"type":"string","maxLength":2000}},"metadata":{"type":"object","properties":{"description":{"type":"string","maxLength":10000}},"required":["description"],"additionalProperties":false}},"required":["common","home","metadata"],"additionalProperties":false}},"required":["name","nickname","initials","url","location","locationLink","description","summary","avatarUrl","skills","navbar","contact","work","education","projects","certifications","copy"],"additionalProperties":false}},"required":["vi","en"],"additionalProperties":false}},"required":["schemaVersion","sections","locales"],"additionalProperties":false}'::json;
 normalized=regexp_replace(doc::text,U&'[\+010000-\+10FFFF]','xx','g')::jsonb;
 if octet_length(doc::text)>240000 or not extensions.jsonb_matches_schema(schema,doc) or not extensions.jsonb_matches_schema(schema,normalized) then return false; end if;
 for n in select * from private.portfolio_nodes(doc) loop
  v=n.value #>> '{}';
  if jsonb_typeof(n.value)='string' and exists(select 1 from generate_series(1,31) c where c not in (9,10,13) and position(chr(c) in v)>0) then return false; end if;
  if n.key in ('href','url','locationLink') then
   if v ~ '[[:space:]\\]' then return false; end if;
   if not (v in ('','#') or v ~ '^/[a-zA-Z0-9/_?=.&%\-]*$' and v !~ '^//' or v ~ '^https://[a-zA-Z0-9][a-zA-Z0-9.-]*([/?#][^[:space:]\\]*)?$' or v ~ '^(mailto|tel):[^[:space:]\\]+$') then return false; end if;
  end if;
  if n.key in ('avatarUrl','logoUrl','image') and not (v='' or regexp_replace(v,'^/','')=any(array['me.jpg','iSOFT_LOGO-nobackground.png','wm.png','geekup.jpg','uit.png','qrtable.webp','multi-vendor.webp','kick.webp','car-garage.webp','meta.png','ibm.png']) or v ~ '^media:[0-9a-f-]{36}$') then return false; end if;
  if jsonb_typeof(n.value)='array' and exists(select 1 from jsonb_array_elements(n.value) e where e ? 'id') and (select count(*)<>count(distinct e->>'id') from jsonb_array_elements(n.value) e) then return false; end if;
 end loop;
 foreach k in array array['work','education','certifications','skills','projects','navbar'] loop
  if (select array_agg(e->>'id' order by e->>'id') from jsonb_array_elements(doc->'locales'->'vi'->k) e) is distinct from (select array_agg(e->>'id' order by e->>'id') from jsonb_array_elements(doc->'locales'->'en'->k) e) then return false; end if;
 end loop;
 if (select array_agg(e->>'id' order by e->>'id') from jsonb_array_elements(doc#>'{locales,vi,contact,social}') e) is distinct from (select array_agg(e->>'id' order by e->>'id') from jsonb_array_elements(doc#>'{locales,en,contact,social}') e) then return false; end if;
 foreach k in array array['vi','en'] loop
  if not coalesce((select array_agg(e->>'id') @> array['GitHub','LinkedIn','Facebook','Instagram'] from jsonb_array_elements(doc->'locales'->k->'contact'->'social') e),false) then return false; end if;
 end loop;
 if (select count(distinct x->>'id') from jsonb_array_elements(doc->'sections') x)<>8 then return false; end if;
 if exists(select 1 from private.portfolio_media_ids(doc) mid where not exists(select 1 from public.portfolio_media m where m.id=mid and m.owner_id=owner)) then return false; end if;
 return true;
exception when others then return false;
end $$;
revoke all on function private.portfolio_nodes(jsonb),private.portfolio_media_ids(jsonb),private.validate_portfolio(jsonb,uuid) from public,anon,authenticated;

create function public.save_portfolio(doc jsonb, expected_revision integer) returns public.portfolio_sites language plpgsql security definer set search_path='' as $$
declare result public.portfolio_sites;
begin
 if not private.is_owner() then raise insufficient_privilege; end if;
 if not private.validate_portfolio(doc,auth.uid()) then raise check_violation using message='invalid_document'; end if;
 if expected_revision=0 then
  insert into public.portfolio_sites(id,owner_id,draft) values(auth.uid(),auth.uid(),doc) on conflict do nothing returning * into result;
 else
  update public.portfolio_sites set draft=doc, revision=revision+1,updated_at=now() where owner_id=auth.uid() and revision=expected_revision returning * into result;
 end if;
 if result.id is null then raise exception 'conflict'; end if;
 return result;
end $$;
create function public.publish_portfolio(expected_revision integer, restore_id uuid default null) returns public.portfolio_versions language plpgsql security definer set search_path='' as $$
declare site public.portfolio_sites; result public.portfolio_versions; doc jsonb;
begin
 if not private.is_owner() then raise insufficient_privilege; end if;
 select * into site from public.portfolio_sites where owner_id=auth.uid() for update;
 if site.id is null then raise exception 'missing'; end if;
 if site.revision<>expected_revision then raise exception 'conflict'; end if;
 doc=site.draft;
 if restore_id is not null then
  select document into doc from public.portfolio_versions where id=restore_id and owner_id=auth.uid();
  if doc is null then raise exception 'missing'; end if;
 end if;
 if not private.validate_portfolio(doc,auth.uid()) then raise check_violation using message='invalid_document'; end if;
 insert into public.portfolio_versions(owner_id,document,draft_revision) values(auth.uid(),doc,site.revision) returning * into result;
 update public.portfolio_sites set published_id=result.id, revision=revision+1, updated_at=now() where id=site.id;
 return result;
end $$;
create function public.read_published_portfolio() returns table(id uuid,document jsonb,created_at timestamptz) language sql stable security definer set search_path='' as $$
 select v.id,v.document,v.created_at from public.portfolio_sites s join public.portfolio_versions v on v.id=s.published_id and v.owner_id=s.owner_id join private.app_owner o on o.user_id=s.owner_id and o.enabled
$$;
create function public.read_published_portfolio_media(media_id uuid) returns table(path text) language sql stable security definer set search_path='' as $$
 select m.path from public.portfolio_media m where m.id=media_id and exists(select 1 from public.read_published_portfolio() p cross join lateral private.portfolio_media_ids(p.document) mid where mid=m.id)
$$;
revoke all on function public.save_portfolio(jsonb,integer),public.publish_portfolio(integer,uuid),public.read_published_portfolio(),public.read_published_portfolio_media(uuid) from public,anon,authenticated;
grant execute on function public.save_portfolio(jsonb,integer),public.publish_portfolio(integer,uuid) to authenticated;
grant execute on function public.read_published_portfolio(),public.read_published_portfolio_media(uuid) to anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolio-media','portfolio-media',false,2097152,array['image/webp']) on conflict(id) do nothing;
create policy portfolio_media_owner_read on storage.objects for select to authenticated using(bucket_id='portfolio-media' and (storage.foldername(name))[1]=auth.uid()::text and (select private.is_owner()));
create policy portfolio_media_owner_upload on storage.objects for insert to authenticated with check(bucket_id='portfolio-media' and name ~ ('^' || auth.uid()::text || '/portfolio/[0-9a-f-]{36}[.]webp$') and (select private.is_owner()));
create policy portfolio_media_published_read on storage.objects for select to anon,authenticated using(bucket_id='portfolio-media' and exists(select 1 from public.read_published_portfolio_media(substring(name from '/portfolio/([0-9a-f-]{36})[.]webp$')::uuid) m where m.path=name));
